'use strict';

// MODULES //

var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var isInfinitef = require( '@stdlib/math/base/assert/is-infinitef' );
var floorf = require( '@stdlib/math/base/special/floorf' );
var powf = require( '@stdlib/math/base/special/powf' );
var toFloat32 = require( '@stdlib/number/float64/base/to-float32' );
var abs = require( '@stdlib/math/base/special/abs' );
var log10 = require( '@stdlib/math/base/special/log10' );


// MAIN //

/**
* Rounds a numeric value to the nearest power of `10` on a linear scale (single-precision).
*
* @param {number} x - input value
* @returns {number} rounded value (float32)
*/
function round10f( x ) {
	var ax;
	var e0;
	var e1;
	var y0;
	var y1;

	// Force float32:
	x = toFloat32( x );

	// Handle specials:
	if ( isnanf( x ) || isInfinitef( x ) || x === 0.0 ) {
		return x;
	}

	// Abs(x):
	ax = toFloat32( abs( x ) );

	// Lower exponent:
	e0 = floorf( log10( ax ) );

	// Next exponent:
	e1 = e0 + 1;

	// Compute two powers:
	y0 = powf( 10.0, e0 );
	y1 = powf( 10.0, e1 );

	// Return whichever is closer:
	if ( (ax - y0) <= (y1 - ax) ) {
		return toFloat32( ( x < 0.0 ) ? -y0 : y0 );
	}
	return toFloat32( ( x < 0.0 ) ? -y1 : y1 );
}


// EXPORTS //

module.exports = round10f;
